from fastapi import APIRouter

router = APIRouter(prefix="/orders")


@router.get("/")
def list_orders(customer_id: int):
    return order_repository.list_for_customer(customer_id)


@router.post("/")
def create_order(payload: OrderCreate):
    inventory.reserve_stock(payload.items)
    order = order_repository.insert(payload)
    email_tasks.send_order_confirmation.delay(order.id)
    return order


@router.delete("/{order_id}")
def cancel_order(order_id: int):
    inventory.release_stock(order_id)
    return order_repository.mark_cancelled(order_id)

