import datetime

ACCESS_TOKEN_EXPIRY_MINUTES = 15


def create_access_token(user_id: int) -> str:
    expiry = datetime.datetime.utcnow() + datetime.timedelta(minutes=ACCESS_TOKEN_EXPIRY_MINUTES)
    return encode({"sub": user_id, "exp": expiry})


def decode_token(token: str) -> dict:
    return decode(token, verify_exp=True)


def refresh_access_token(token: str) -> str:
    claims = decode_token(token)
    return create_access_token(claims["sub"])

class PaymentService:
    """Charges customers through Stripe."""

    MAX_RETRIES = 3

    def charge(self, order_id: int, amount_cents: int) -> str:
        idempotency_key = f"order-{order_id}"
        for attempt in range(self.MAX_RETRIES):
            try:
                return stripe.charge(amount_cents, idempotency_key=idempotency_key)
            except StripeTimeout:
                continue
        raise PaymentFailed(order_id)

class RefundService:
    def refund(self, order_id: int, amount_cents: int | None = None) -> str:
        payment = payments.get_for_order(order_id)
        # partial refunds pass an explicit amount
        amount = amount_cents or payment.amount_cents
        return stripe.refund(payment.charge_id, amount)

LIST_SQL = """
SELECT o.id, o.status, o.total_cents, c.email
FROM orders o JOIN customers c ON c.id = o.customer_id
WHERE o.customer_id = :customer_id
"""


def list_for_customer(customer_id: int):
    return db.execute(LIST_SQL, {"customer_id": customer_id}).all()


def insert(payload):
    return db.execute("INSERT INTO orders (customer_id, status) VALUES (:c, 'new')", {"c": payload.customer_id})


def mark_cancelled(order_id: int):
    return db.execute("UPDATE orders SET status = 'cancelled' WHERE id = :id", {"id": order_id})

@celery_app.task(bind=True, max_retries=5)
def send_order_confirmation(self, order_id: int) -> None:
    order = order_repository.get(order_id)
    try:
        mailer.send(to=order.customer_email, template="order_confirmation", order=order)
    except MailerUnavailable as exc:
        raise self.retry(exc=exc, countdown=60)

def reserve_stock(items) -> None:
    for item in items:
        redis.decrby(f"stock:{item.sku}", item.quantity)


def release_stock(order_id: int) -> None:
    for item in order_items.for_order(order_id):
        redis.incrby(f"stock:{item.sku}", item.quantity)

CATALOG_TTL_SECONDS = 300


def get_product_catalog():
    cached = redis.get("catalog")
    if cached:
        return json.loads(cached)
    catalog = products.load_all()
    redis.setex("catalog", CATALOG_TTL_SECONDS, json.dumps(catalog))
    return catalog


def invalidate_catalog():
    redis.delete("catalog")

